    "metadata": "{\"compiler\":{\"version\":\"0.8.28+commit.7893614a\"},\"language\":\"Solidity\",\"output\":{\"abi\":[{\"inputs\":[],\"name\":\"read\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"readBurn\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"oracleValue\",\"type\":\"uint256\"},{\"internalType\":\"uint256\",\"name\":\"ratio\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"readMint\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"readRedemption\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"}],\"devdoc\":{\"author\":\"Cooper Labs\",\"custom:contact\":\"security@cooperlabs.xyz\",\"details\":\"This interface is an authorized fork of Angle's `ITransmuterOracle` interface https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/interfaces/ITransmuterOracle.sol\",\"kind\":\"dev\",\"methods\":{},\"title\":\"IParallelizerOracle\",\"version\":1},\"userdoc\":{\"kind\":\"user\",\"methods\":{\"read()\":{\"notice\":\"Reads the oracle value for asset\"},\"readBurn()\":{\"notice\":\"Reads the oracle value for asset to use in a burn transaction as well as the ratio between the current price and the target price for the asset\"},\"readMint()\":{\"notice\":\"Reads the oracle value for asset to use in a mint. It should be comprehensive of the deviation from the target price\"},\"readRedemption()\":{\"notice\":\"Reads the oracle value for asset to use in a redemption to compute the collateral ratio\"}},\"version\":1}},\"settings\":{\"compilationTarget\":{\"project/contracts/interfaces/IParallelizerOracle.sol\":\"IParallelizerOracle\"},\"evmVersion\":\"cancun\",\"libraries\":{},\"metadata\":{\"bytecodeHash\":\"ipfs\",\"useLiteralContent\":true},\"optimizer\":{\"enabled\":true,\"runs\":1000},\"remappings\":[\"npm/@openzeppelin/contracts-upgradeable@5.4.0/:@openzeppelin/contracts/=npm/@openzeppelin/contracts@5.4.0/\",\"project/:@helpers/=project/libs/helpers/\",\"project/:@openzeppelin/contracts-upgradeable/=npm/@openzeppelin/contracts-upgradeable@5.4.0/\",\"project/:@openzeppelin/contracts/=npm/@openzeppelin/contracts@5.4.0/\",\"project/:contracts/=project/contracts/\"],\"viaIR\":true},\"sources\":{\"project/contracts/interfaces/IParallelizerOracle.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\npragma solidity 0.8.28;\\n\\n/// @title IParallelizerOracle\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @dev This interface is an authorized fork of Angle's `ITransmuterOracle` interface\\n/// https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/interfaces/ITransmuterOracle.sol\\ninterface IParallelizerOracle {\\n  /// @notice Reads the oracle value for asset to use in a redemption to compute the collateral ratio\\n  function readRedemption() external view returns (uint256);\\n\\n  /// @notice Reads the oracle value for asset to use in a mint. It should be comprehensive of the\\n  /// deviation from the target price\\n  function readMint() external view returns (uint256);\\n\\n  /// @notice Reads the oracle value for asset to use in a burn transaction as well as the ratio\\n  /// between the current price and the target price for the asset\\n  function readBurn() external view returns (uint256 oracleValue, uint256 ratio);\\n\\n  /// @notice Reads the oracle value for asset\\n  function read() external view returns (uint256);\\n}\\n\",\"keccak256\":\"0x1efe82def8da7cdbf7378004558354bfc63610f40760e56340f6b4c5bb1273e6\",\"license\":\"GPL-3.0\"}},\"version\":1}",
