    "inputSourceName": "project/contracts/interfaces/ITokenP.sol",
    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "This interface is an authorized fork of Angle's `IAgToken` interface https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/interfaces/IAgToken.sol",
      "events": {
        "Approval(address,address,uint256)": {
          "details": "Emitted when the allowance of a `spender` for an `owner` is set by a call to {approve}. `value` is the new allowance."
        },
        "Transfer(address,address,uint256)": {
          "details": "Emitted when `value` tokens are moved from one account (`from`) to another (`to`). Note that `value` may be zero."
        }
      },
      "kind": "dev",
      "methods": {
        "allowance(address,address)": {
          "details": "Returns the remaining number of tokens that `spender` will be allowed to spend on behalf of `owner` through {transferFrom}. This is zero by default. This value changes when {approve} or {transferFrom} are called."
        },
        "approve(address,uint256)": {
          "details": "Sets a `value` amount of tokens as the allowance of `spender` over the caller's tokens. Returns a boolean value indicating whether the operation succeeded. IMPORTANT: Beware that changing an allowance with this method brings the risk that someone may use both the old and the new allowance by unfortunate transaction ordering. One possible solution to mitigate this race condition is to first reduce the spender's allowance to 0 and set the desired value afterwards: https://github.com/ethereum/EIPs/issues/20#issuecomment-263524729 Emits an {Approval} event."
        },
        "balanceOf(address)": {
          "details": "Returns the value of tokens owned by `account`."
        },
        "burnFrom(uint256,address,address)": {
          "details": "This method is to be called by a contract with the minter right after being requested to do so by a `sender` address willing to burn tokens from another `burner` addressThe method checks the allowance between the `sender` and the `burner`",
          "params": {
            "amount": "Amount of tokens to burn",
            "burner": "Address to burn from",
            "sender": "Address which requested the burn from `burner`"
          }
        },
        "burnSelf(uint256,address)": {
          "details": "This method is to be called by a contract with a minter right on the tokenP after being requested to do so by an address willing to burn tokens from its address",
          "params": {
            "amount": "Amount of tokens to burn",
            "burner": "Address to burn from"
          }
        },
        "mint(address,uint256)": {
          "params": {
            "account": "Address to mint to",
            "amount": "Amount to mint"
          }
        },
        "totalSupply()": {
          "details": "Returns the value of tokens in existence."
        },
        "transfer(address,uint256)": {
          "details": "Moves a `value` amount of tokens from the caller's account to `to`. Returns a boolean value indicating whether the operation succeeded. Emits a {Transfer} event."
        },
        "transferFrom(address,address,uint256)": {
          "details": "Moves a `value` amount of tokens from `from` to `to` using the allowance mechanism. `value` is then deducted from the caller's allowance. Returns a boolean value indicating whether the operation succeeded. Emits a {Transfer} event."
        }
      },
      "title": "ITokenP",
      "version": 1
    },
