    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "This contract is an authorized fork of Angle's `SettersGovernor` contract https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/transmuter/facets/SettersGovernor.sol",
      "errors": {
        "SafeCastOverflowedUintDowncast(uint8,uint256)": [
          {
            "details": "Value doesn't fit in an uint of `bits` size."
          }
        ],
        "SafeERC20FailedDecreaseAllowance(address,uint256,uint256)": [
          {
            "details": "Indicates a failed `decreaseAllowance` request."
          }
        ],
        "SafeERC20FailedOperation(address)": [
          {
            "details": "An operation with an ERC-20 token failed."
          }
        ]
      },
      "kind": "dev",
      "methods": {
        "addCollateral(address)": {
          "details": "Collateral assets with a fee on transfer are not supported by the system"
        },
        "adjustStablecoins(address,uint128,bool)": {
          "details": "The amount passed here must be an absolute amount"
        },
        "changeAllowance(address,address,uint256)": {
          "details": "This function can typically be used to grant allowance to a newly added manager for it to pull the funds associated to the collateral it corresponds to"
        },
        "recoverERC20(address,address,address,uint256)": {
          "details": "No check is made on the collateral that is redeemed: this function could typically be used by a governance during a manual rebalance of the reserves of the system`collateral` is different from `token` only in the case of a managed collateral"
        },
        "revokeCollateral(address,bool)": {
          "details": "Require `collatInfo.normalizedStables == 0`, that is to say that the collateral is not used to back stablesThe system may still have a non null balance of the collateral that is revoked: this should later be handled through a recoverERC20 callFunds needs to have been withdrew from the manager prior to this call if `checkExternalManagerBalance` is true"
        },
        "setCollateralManager(address,bool,(address[],bytes))": {
          "details": "Funds need to have been withdrawn from the eventual previous manager prior to this call"
        },
        "updatePayees(address[],uint256[],bool)": {
          "params": {
            "_payees": "The new payee addresses",
            "_shares": "The new shares for each payee",
            "_skipRelease": "If true, skips the automatic income release before updating"
          }
        },
        "updateSlippageTolerance(address,uint256)": {
          "details": "Maximum slippage tolerance is 1e9 (100%)The slippage tolerance is used to compute the minimum expected amount of stablecoins to be received when calling the `processSurplus` function"
        },
        "updateSurplusBufferRatio(uint64)": {
          "details": "The surplus buffer ratio is the minimum collateral ratio required after surplus processing",
          "params": {
            "_surplusBufferRatio": "The new surplus buffer ratio in BASE_9"
          }
        }
      },
      "title": "SettersGovernor",
      "version": 1
    },
