    "inputSourceName": "project/contracts/savings/EIP3009.sol",
    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "Provides internal implementations that inheriting contracts must wrap with public functions. Supports both EOA (v,r,s) and smart contract wallet (EIP-1271) signatures. The EIP-712 domain separator is computed dynamically from `name()` so no initialization is required.",
      "errors": {
        "ERC20InsufficientAllowance(address,uint256,uint256)": [
          {
            "details": "Indicates a failure with the `spender`’s `allowance`. Used in transfers.",
            "params": {
              "allowance": "Amount of tokens a `spender` is allowed to operate with.",
              "needed": "Minimum amount required to perform a transfer.",
              "spender": "Address that may be allowed to operate on tokens without being their owner."
            }
          }
        ],
        "ERC20InsufficientBalance(address,uint256,uint256)": [
          {
            "details": "Indicates an error related to the current `balance` of a `sender`. Used in transfers.",
            "params": {
              "balance": "Current balance for the interacting account.",
              "needed": "Minimum amount required to perform a transfer.",
              "sender": "Address whose tokens are being transferred."
            }
          }
        ],
        "ERC20InvalidApprover(address)": [
          {
            "details": "Indicates a failure with the `approver` of a token to be approved. Used in approvals.",
            "params": {
              "approver": "Address initiating an approval operation."
            }
          }
        ],
        "ERC20InvalidReceiver(address)": [
          {
            "details": "Indicates a failure with the token `receiver`. Used in transfers.",
            "params": {
              "receiver": "Address to which tokens are being transferred."
            }
          }
        ],
        "ERC20InvalidSender(address)": [
          {
            "details": "Indicates a failure with the token `sender`. Used in transfers.",
            "params": {
              "sender": "Address whose tokens are being transferred."
            }
          }
        ],
        "ERC20InvalidSpender(address)": [
          {
            "details": "Indicates a failure with the `spender` to be approved. Used in approvals.",
            "params": {
              "spender": "Address that may be allowed to operate on tokens without being their owner."
            }
          }
        ],
        "InvalidInitialization()": [
          {
            "details": "The contract is already initialized."
          }
        ],
        "NotInitializing()": [
          {
            "details": "The contract is not initializing."
          }
        ]
      },
      "events": {
        "Approval(address,address,uint256)": {
          "details": "Emitted when the allowance of a `spender` for an `owner` is set by a call to {approve}. `value` is the new allowance."
        },
        "Initialized(uint64)": {
          "details": "Triggered when the contract has been initialized or reinitialized."
        },
        "Transfer(address,address,uint256)": {
          "details": "Emitted when `value` tokens are moved from one account (`from`) to another (`to`). Note that `value` may be zero."
        }
      },
      "kind": "dev",
      "methods": {
        "allowance(address,address)": {
          "details": "Returns the remaining number of tokens that `spender` will be allowed to spend on behalf of `owner` through {transferFrom}. This is zero by default. This value changes when {approve} or {transferFrom} are called."
        },
        "approve(address,uint256)": {
          "details": "See {IERC20-approve}. NOTE: If `value` is the maximum `uint256`, the allowance is not updated on `transferFrom`. This is semantically equivalent to an infinite approval. Requirements: - `spender` cannot be the zero address."
        },
        "balanceOf(address)": {
          "details": "Returns the value of tokens owned by `account`."
        },
        "decimals()": {
          "details": "Returns the number of decimals used to get its user representation. For example, if `decimals` equals `2`, a balance of `505` tokens should be displayed to a user as `5.05` (`505 / 10 ** 2`). Tokens usually opt for a value of 18, imitating the relationship between Ether and Wei. This is the default value returned by this function, unless it's overridden. NOTE: This information is only used for _display_ purposes: it in no way affects any of the arithmetic of the contract, including {IERC20-balanceOf} and {IERC20-transfer}."
        },
        "name()": {
          "details": "Returns the name of the token."
        },
        "receiveWithAuthorization(address,address,uint256,uint256,uint256,bytes32,uint8,bytes32,bytes32)": {
          "details": "This has an additional check to ensure that the payee's address matches the caller of this function to prevent front-running attacks",
          "params": {
            "from": "Payer's address (Authorizer)",
            "nonce": "Unique nonce",
            "r": "r of the signature",
            "s": "s of the signature",
            "to": "Payee's address (must be msg.sender)",
            "v": "v of the signature",
            "validAfter": "The time after which this is valid (unix time)",
            "validBefore": "The time before which this is valid (unix time)",
            "value": "Amount to be transferred"
          }
        },
        "symbol()": {
          "details": "Returns the symbol of the token, usually a shorter version of the name."
        },
        "totalSupply()": {
          "details": "Returns the value of tokens in existence."
        },
        "transfer(address,uint256)": {
          "details": "See {IERC20-transfer}. Requirements: - `to` cannot be the zero address. - the caller must have a balance of at least `value`."
        },
        "transferFrom(address,address,uint256)": {
          "details": "See {IERC20-transferFrom}. Skips emitting an {Approval} event indicating an allowance update. This is not required by the ERC. See {xref-ERC20-_approve-address-address-uint256-bool-}[_approve]. NOTE: Does not update the allowance if the current allowance is the maximum `uint256`. Requirements: - `from` and `to` cannot be the zero address. - `from` must have a balance of at least `value`. - the caller must have allowance for ``from``'s tokens of at least `value`."
        },
        "transferWithAuthorization(address,address,uint256,uint256,uint256,bytes32,uint8,bytes32,bytes32)": {
          "params": {
            "from": "Payer's address (Authorizer)",
            "nonce": "Unique nonce",
            "r": "r of the signature",
            "s": "s of the signature",
            "to": "Payee's address",
            "v": "v of the signature",
            "validAfter": "The time after which this is valid (unix time)",
            "validBefore": "The time before which this is valid (unix time)",
            "value": "Amount to be transferred"
          }
        }
      },
      "title": "EIP3009",
      "version": 1
    },
