n            // This opcode adds new most significant bits set to the value of the previous most significant bit. As a result,\\n            // the mask will either be `bytes32(0)` (if n is positive) or `~bytes32(0)` (if n is negative).\\n            int256 mask = n >> 255;\\n\\n            // A `bytes32(0)` mask leaves the input unchanged, while a `~bytes32(0)` mask complements it.\\n            return uint256((n + mask) ^ mask);\\n        }\\n    }\\n}\\n\",\"keccak256\":\"0xb1970fac7b64e6c09611e6691791e848d5e3fe410fa5899e7df2e0afd77a99e3\",\"license\":\"MIT\"},\"project/contracts/interfaces/ITokenP.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\npragma solidity 0.8.28;\\n\\nimport { IERC20 } from \\\"@openzeppelin/contracts/token/ERC20/IERC20.sol\\\";\\n\\n/// @title ITokenP\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @notice Interface for the stablecoins `tokenP` contracts\\n/// @dev This interface is an authorized fork of Angle's `IAgToken` interface\\n/// https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/interfaces/IAgToken.sol\\ninterface ITokenP is IERC20 {\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    MINTER ROLE ONLY FUNCTIONS                                            \\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Lets a whitelisted contract mint tokenPs\\n  /// @param account Address to mint to\\n  /// @param amount Amount to mint\\n  function mint(address account, uint256 amount) external;\\n\\n  /// @notice Burns `amount` tokens from a `burner` address after being asked to by `sender`\\n  /// @param amount Amount of tokens to burn\\n  /// @param burner Address to burn from\\n  /// @param sender Address which requested the burn from `burner`\\n  /// @dev This method is to be called by a contract with the minter right after being requested\\n  /// to do so by a `sender` address willing to burn tokens from another `burner` address\\n  /// @dev The method checks the allowance between the `sender` and the `burner`\\n  function burnFrom(uint256 amount, address burner, address sender) external;\\n\\n  /// @notice Burns `amount` tokens from a `burner` address\\n  /// @param amount Amount of tokens to burn\\n  /// @param burner Address to burn from\\n  /// @dev This method is to be called by a contract with a minter right on the tokenP after being\\n  /// requested to do so by an address willing to burn tokens from its address\\n  function burnSelf(uint256 amount, address burner) external;\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    EXTERNAL FUNCTIONS                                                \\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Amount of decimals of the stablecoin\\n  function decimals() external view returns (uint8);\\n}\\n\",\"keccak256\":\"0x64a1305faa8c5c91767a11af0eae16e4b463aa0bfe10f11b74aae9d96681a5eb\",\"license\":\"GPL-3.0\"},\"project/contracts/interfaces/external/IEIP3009.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\npragma solidity 0.8.28;\\n\\n/// @title IEIP3009\\n/// @notice Interface for EIP-3009: Transfer With Authorization\\n/// @dev https://eips.ethereum.org/EIPS/eip-3009\\ninterface IEIP3009 {\\n  /// @notice Execute a transfer with a signed authorization\\n  /// @param from Payer's address (Authorizer)\\n  /// @param to Payee's address\\n  /// @param value Amount to be transferred\\n  /// @param validAfter The time after which this is valid (unix time)\\n  /// @param validBefore The time before which this is valid (unix time)\\n  /// @param nonce Unique nonce\\n  /// @param v v of the signature\\n  /// @param r r of the signature\\n  /// @param s s of the signature\\n  function transferWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    external;\\n\\n  /// @notice Receive a transfer with a signed authorization from the payer\\n  /// @dev This has an additional check to ensure that the payee's address matches\\n  /// the caller of this function to prevent front-running attacks\\n  /// @param from Payer's address (Authorizer)\\n  /// @param to Payee's address (must be msg.sender)\\n  /// @param value Amount to be transferred\\n  /// @param validAfter The time after which this is valid (unix time)\\n  /// @param validBefore The time before which this is valid (unix time)\\n  /// @param nonce Unique nonce\\n  /// @param v v of the signature\\n  /// @param r r of the signature\\n  /// @param s s of the signature\\n  function receiveWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    external;\\n}\\n\",\"keccak256\":\"0x34187f0b921d5edba40ba62349720fc0d9e2841d5f0e0abe6567ae20f71229ad\",\"license\":\"MIT\"},\"project/contracts/interfaces/external/coinbase/ICbETH.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\n\\npragma solidity >=0.5.0;\\n\\n/// @title ICbETH\\n/// @notice Interface for the `cbETH` contract\\ninterface ICbETH {\\n  function exchangeRate() external view returns (uint256);\\n}\\n\",\"keccak256\":\"0xb159341cb0e25c478912b274cdda2d50fa84692aeac87b6823d281aaea2aed04\",\"license\":\"GPL-3.0\"},\"project/contracts/interfaces/external/frax/ISfrxETH.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\n\\npragma solidity >=0.5.0;\\n\\n/// @title ISfrxETH\\n/// @notice Interface for the `sfrxETH` contract\\ninterface ISfrxETH {\\n  function pricePerShare() external view returns (uint256);\\n}\\n\",\"keccak256\":\"0x914cbea276f817c7db62bfca21e15bd8f7892faa9f39d86baaef574cf12b859f\",\"license\":\"GPL-3.0\"},\"project/contracts/interfaces/external/lido/IStETH.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\n\\npragma solidity >=0.5.0;\\n\\n/// @title IStETH\\n/// @notice Interface for the `StETH` contract\\ninterface IStETH {\\n  function getPooledEthByShares(uint256 _sharesAmount) external view returns (uint256);\\n\\n  function submit(address) external payable returns (uint256);\\n\\n  function getSharesByPooledEth(uint256 _ethAmount) external view returns (uint256);\\n}\\n\",\"keccak256\":\"0xf21e3d8bdadc236b34bf2122b0e0b939d2d6bb6e2889b508636cbb7b84f59680\",\"license\":\"GPL-3.0\"},\"project/contracts/interfaces/external/rocketPool/IRETH.sol\":{\"content\":\"// SPDX-License-Identifier: GPL-3.0\\n\\npragma solidity >=0.5.0;\\n\\n/// @title IRETH\\n/// @notice Interface for the `rETH` contract\\ninterface IRETH {\\n  function getExchangeRate() external view returns (uint256);\\n}\\n\",\"keccak256\":\"0x567a378e95d40160e297c1adb617ccaa69c03e49c4ad72a6ce651dd43cdbd5cd\",\"license\":\"GPL-3.0\"},\"project/contracts/savings/BaseSavings.sol\":{\"content\":\"// SPDX-License-Identifier: BUSL-1.1\\npragma solidity 0.8.28;\\n\\nimport { ERC4626Upgradeable } from \\\"@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC4626Upgradeable.sol\\\";\\nimport { ERC20Upgradeable } from \\\"@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol\\\";\\nimport { UUPSUpgradeable } from \\\"@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol\\\";\\nimport { Initializable } from \\\"@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol\\\";\\nimport { IERC20Metadata } from \\\"@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol\\\";\\nimport { SafeERC20 } from \\\"@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol\\\";\\nimport { Math } from \\\"@openzeppelin/contracts/utils/math/Math.sol\\\";\\n\\nimport { ITokenP } from \\\"contracts/interfaces/ITokenP.sol\\\";\\nimport { AccessManagedUpgradeable, IAccessManager } from \\\"../utils/AccessManagedUpgradeable.sol\\\";\\n\\nimport \\\"../utils/Constants.sol\\\";\\nimport \\\"../utils/Errors.sol\\\";\\n\\n/// @title BaseSavings\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @notice Parallel Savings contracts are contracts where users can deposit an `asset` and earn a yield on this asset\\n/// when it is distributed\\n/// @dev These contracts are functional within the Parallelizer system if they have mint right on `asset` and\\n/// if they are trusted by the Parallelizer contract\\n/// @dev Implementations assume that `asset` is safe to interact with, on which there cannot be reentrancy attacks\\n/// @dev The ERC4626 interface does not allow users to specify a slippage protection parameter for the main entry\\n/// points\\n/// (like `deposit`, `mint`, `redeem` or `withdraw`). Even though there should be no specific sandwiching\\n/// issue with current implementations, it is still recommended to interact with Parallel Savings contracts\\n/// through a router that can implement such a protection.\\n/// @dev This contract is an authorized fork of Angle's Savings contract:\\n/// https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/savings/BaseSavings.sol\\nabstract contract BaseSavings is Initializable, AccessManagedUpgradeable, ERC4626Upgradeable, UUPSUpgradeable {\\n  /// @custom:oz-upgrades-unsafe-allow constructor\\n  constructor() {\\n    _disableInitializers();\\n  }\\n\\n  /// @notice Upgrade the implementation of the contract\\n  /// @dev This function can only be called by the governor only\\n  /// @param newImplementation The address of the new implementation\\n  function _authorizeUpgrade(address newImplementation) internal override restricted { }\\n}\\n\",\"keccak256\":\"0x06f591d6fe6fe004433a7983330d9cc45d27d69c2cf9693804c43c1a49272596\",\"license\":\"BUSL-1.1\"},\"project/contracts/savings/EIP3009.sol\":{\"content\":\"// SPDX-License-Identifier: BUSL-1.1\\npragma solidity 0.8.28;\\n\\nimport { ERC20Upgradeable } from \\\"@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol\\\";\\nimport { SignatureChecker } from \\\"@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol\\\";\\nimport { MessageHashUtils } from \\\"@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol\\\";\\n\\nimport { IEIP3009 } from \\\"contracts/interfaces/external/IEIP3009.sol\\\";\\n\\n/// @title EIP3009\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @notice Abstract implementation of EIP-3009: Transfer With Authorization\\n/// @dev Provides internal implementations that inheriting contracts must wrap with public functions.\\n/// Supports both EOA (v,r,s) and smart contract wallet (EIP-1271) signatures.\\n/// The EIP-712 domain separator is computed dynamically from `name()` so no initialization is required.\\nabstract contract EIP3009 is ERC20Upgradeable, IEIP3009 {\\n  // keccak256(\\\"TransferWithAuthorization(address from,address to,\\n  //   uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)\\\")\\n  bytes32 public constant TRANSFER_WITH_AUTHORIZATION_TYPEHASH =\\n    0x7c7c6cdb67a18743f49ec6fa9b35f50d52ed05cbed4cc592e13b44501c1a2267;\\n\\n  // keccak256(\\\"ReceiveWithAuthorization(address from,address to,\\n  //   uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)\\\")\\n  bytes32 public constant RECEIVE_WITH_AUTHORIZATION_TYPEHASH =\\n    0xd099cc98ef71107a616c4f0f941f04c322d8e254fe26b3c6668db87aae413de8;\\n\\n  // keccak256(\\\"CancelAuthorization(address authorizer,bytes32 nonce)\\\")\\n  bytes32 public constant CANCEL_AUTHORIZATION_TYPEHASH =\\n    0x158b0a9edf7a828aad02f63cd515c68ef2f50ba807396f6d12842833a1597429;\\n\\n  bytes32 private constant EIP712_DOMAIN_TYPEHASH =\\n    keccak256(\\\"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)\\\");\\n\\n  bytes32 private constant VERSION_HASH = keccak256(bytes(\\\"1\\\"));\\n\\n  /// @custom:storage-location erc7201:cooperlabs.storage.EIP3009\\n  struct EIP3009Storage {\\n    mapping(address => mapping(bytes32 => bool)) authorizationStates;\\n  }\\n\\n  // keccak256(abi.encode(uint256(keccak256(\\\"cooperlabs.storage.EIP3009\\\")) - 1)) & ~bytes32(uint256(0xff))\\n  bytes32 private constant EIP3009StorageLocation = 0x0f2e86d677e57958274060fd7e3f94ab58d8026e3c78e0e811418ca3fbe98e00;\\n\\n  function _getEIP3009Storage() private pure returns (EIP3009Storage storage $) {\\n    assembly {\\n      $.slot := EIP3009StorageLocation\\n    }\\n  }\\n\\n  event AuthorizationUsed(address indexed authorizer, bytes32 indexed nonce);\\n  event AuthorizationCanceled(address indexed authorizer, bytes32 indexed nonce);\\n\\n  error AuthorizationNotYetValid();\\n  error AuthorizationExpired();\\n  error AuthorizationAlreadyUsed(bytes32 nonce);\\n  error CallerMustBePayee();\\n  error InvalidSignature();\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    VIEW FUNCTIONS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  function authorizationState(address authorizer, bytes32 nonce) external view returns (bool) {\\n    return _getEIP3009Storage().authorizationStates[authorizer][nonce];\\n  }\\n\\n  // solhint-disable-next-line func-name-mixedcase\\n  function DOMAIN_SEPARATOR() external view returns (bytes32) {\\n    return _domainSeparator();\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    INTERNAL FUNCTIONS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  function _transferWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    internal\\n  {\\n    _transferWithAuthorization(from, to, value, validAfter, validBefore, nonce, abi.encodePacked(r, s, v));\\n  }\\n\\n  function _transferWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    bytes memory signature\\n  )\\n    internal\\n  {\\n    _requireValidAuthorization(from, nonce, validAfter, validBefore);\\n    _requireValidSignature(\\n      from,\\n      keccak256(abi.encode(TRANSFER_WITH_AUTHORIZATION_TYPEHASH, from, to, value, validAfter, validBefore, nonce)),\\n      signature\\n    );\\n    _markAuthorizationAsUsed(from, nonce);\\n    _transfer(from, to, value);\\n  }\\n\\n  function _receiveWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    internal\\n  {\\n    _receiveWithAuthorization(from, to, value, validAfter, validBefore, nonce, abi.encodePacked(r, s, v));\\n  }\\n\\n  function _receiveWithAuthorization(\\n    address from,\\n    address to,\\n    uint256 value,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    bytes memory signature\\n  )\\n    internal\\n  {\\n    if (to != msg.sender) revert CallerMustBePayee();\\n    _requireValidAuthorization(from, nonce, validAfter, validBefore);\\n    _requireValidSignature(\\n      from,\\n      keccak256(abi.encode(RECEIVE_WITH_AUTHORIZATION_TYPEHASH, from, to, value, validAfter, validBefore, nonce)),\\n      signature\\n    );\\n    _markAuthorizationAsUsed(from, nonce);\\n    _transfer(from, to, value);\\n  }\\n\\n  function _cancelAuthorization(address authorizer, bytes32 nonce, uint8 v, bytes32 r, bytes32 s) internal {\\n    _cancelAuthorization(authorizer, nonce, abi.encodePacked(r, s, v));\\n  }\\n\\n  function _cancelAuthorization(address authorizer, bytes32 nonce, bytes memory signature) internal {\\n    _requireUnusedAuthorization(authorizer, nonce);\\n    _requireValidSignature(\\n      authorizer,\\n      keccak256(abi.encode(CANCEL_AUTHORIZATION_TYPEHASH, authorizer, nonce)),\\n      signature\\n    );\\n    _getEIP3009Storage().authorizationStates[authorizer][nonce] = true;\\n    emit AuthorizationCanceled(authorizer, nonce);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    PRIVATE HELPERS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  function _domainSeparator() internal view returns (bytes32) {\\n    return keccak256(\\n      abi.encode(EIP712_DOMAIN_TYPEHASH, keccak256(bytes(name())), VERSION_HASH, block.chainid, address(this))\\n    );\\n  }\\n\\n  function _requireValidSignature(\\n    address signer, bytes32 dataHash, bytes memory signature\\n  ) private view {\\n    bytes32 digest = MessageHashUtils.toTypedDataHash(_domainSeparator(), dataHash);\\n    if (!SignatureChecker.isValidSignatureNow(signer, digest, signature)) {\\n      revert InvalidSignature();\\n    }\\n  }\\n\\n  function _requireValidAuthorization(\\n    address authorizer, bytes32 nonce, uint256 validAfter, uint256 validBefore\\n  ) private view {\\n    if (block.timestamp <= validAfter) revert AuthorizationNotYetValid();\\n    if (block.timestamp >= validBefore) revert AuthorizationExpired();\\n    _requireUnusedAuthorization(authorizer, nonce);\\n  }\\n\\n  function _requireUnusedAuthorization(address authorizer, bytes32 nonce) private view {\\n    if (_getEIP3009Storage().authorizationStates[authorizer][nonce]) revert AuthorizationAlreadyUsed(nonce);\\n  }\\n\\n  function _markAuthorizationAsUsed(address authorizer, bytes32 nonce) private {\\n    _getEIP3009Storage().authorizationStates[authorizer][nonce] = true;\\n    emit AuthorizationUsed(authorizer, nonce);\\n  }\\n}\\n\",\"keccak256\":\"0x2be430bf16a4674863b63210612d04441520b83d0edde71b431d6e793548be7c\",\"license\":\"BUSL-1.1\"},\"project/contracts/savings/Savings.sol\":{\"content\":\"// SPDX-License-Identifier: BUSL-1.1\\npragma solidity 0.8.28;\\n\\nimport { IEIP3009 } from \\\"contracts/interfaces/external/IEIP3009.sol\\\";\\n\\nimport \\\"./BaseSavings.sol\\\";\\nimport \\\"./EIP3009.sol\\\";\\n\\n/// @title Savings\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @notice In this implementation, assets in the contract increase in value following a `rate` chosen by governance\\n/// @dev This contract is an authorized fork of Angle's Savings contract:\\n/// https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/savings/Savings.sol\\ncontract Savings is BaseSavings, EIP3009 {\\n  using SafeERC20 for IERC20Metadata;\\n  using Math for uint256;\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    PARAMETERS / REFERENCES\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Inflation rate (per second) in BASE_27\\n  uint208 public rate;\\n\\n  /// @notice Last time rewards were accrued\\n  uint40 public lastUpdate;\\n\\n  /// @notice Whether the contract is paused or not\\n  uint8 public paused;\\n\\n  /// @notice Maximum inflation rate\\n  /// @dev Note that `rate` can still be greater than `maxRate` if this `maxRate` is reduced by governance\\n  /// to a level inferior to the current rate\\n  uint256 public maxRate;\\n\\n  /// @notice Checks whether the address is trusted to set the rate\\n  mapping(address => uint256) public isTrustedUpdater;\\n\\n  uint256[48] private __gap;\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    EVENTS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  event Accrued(uint256 interest);\\n  event MaxRateUpdated(uint256 newMaxRate);\\n  event ToggledPause(uint128 pauseStatus);\\n  event ToggledTrusted(address indexed trustedAddress, uint256 trustedStatus);\\n  event RateUpdated(uint256 newRate);\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    INITIALIZATION\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Initializes the contract\\n  /// @param _authority Reference to the `AccessManagerContract` contract\\n  /// @param name_ Name of the savings contract\\n  /// @param symbol_ Symbol of the savings contract\\n  /// @param divizer Quantifies the first initial deposit (should be typically 1 for tokens like agEUR)\\n  /// @dev A first deposit is done at initialization to protect for the classical issue of ERC4626 contracts\\n  /// where the the first user of the contract tries to steal everyone else's tokens\\n  function initialize(\\n    address _authority,\\n    IERC20Metadata asset_,\\n    string memory name_,\\n    string memory symbol_,\\n    uint256 divizer\\n  )\\n    public\\n    initializer\\n  {\\n    if (address(_authority) == address(0)) revert ZeroAddress();\\n    __ERC4626_init(asset_);\\n    __ERC20_init(name_, symbol_);\\n    __UUPSUpgradeable_init();\\n    __AccessManaged_init(_authority);\\n    _setNameAndSymbol(name_, symbol_);\\n    _deposit(msg.sender, address(this), 10 ** (asset_.decimals()) / divizer, BASE_18 / divizer);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    MODIFIERS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Checks whether the whole contract is paused or not\\n  modifier whenNotPaused() {\\n    if (paused > 0) revert Paused();\\n    _;\\n  }\\n\\n  /// @notice Checks whether the sender is allowed to update the rate\\n  modifier onlyTrustedOrRestricted() {\\n    if (isTrustedUpdater[msg.sender] == 0 && !_checkCanCall(_msgSender(), _msgData())) {\\n      revert NotTrusted();\\n    }\\n    _;\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    CONTRACT LOGIC\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Accrues interest to this contract by minting tokenPs\\n  function _accrue() internal returns (uint256 newTotalAssets) {\\n    uint256 currentBalance = super.totalAssets();\\n    newTotalAssets = _computeUpdatedAssets(currentBalance, block.timestamp - lastUpdate);\\n    lastUpdate = uint40(block.timestamp);\\n    uint256 earned = newTotalAssets - currentBalance;\\n    if (earned > 0) {\\n      ITokenP(asset()).mint(address(this), earned);\\n      emit Accrued(earned);\\n    }\\n  }\\n\\n  /// @notice Computes how much `currentBalance` held in the contract would be after `exp` time following\\n  /// the `rate` of increase\\n  function _computeUpdatedAssets(uint256 currentBalance, uint256 exp) internal view returns (uint256) {\\n    uint256 ratePerSecond = rate;\\n    if (exp == 0 || ratePerSecond == 0) return currentBalance;\\n    uint256 expMinusOne = exp - 1;\\n    uint256 expMinusTwo = exp > 2 ? exp - 2 : 0;\\n    uint256 basePowerTwo = (ratePerSecond * ratePerSecond + HALF_BASE_27) / BASE_27;\\n    uint256 basePowerThree = (basePowerTwo * ratePerSecond + HALF_BASE_27) / BASE_27;\\n    uint256 secondTerm = (exp * expMinusOne * basePowerTwo) / 2;\\n    uint256 thirdTerm = (exp * expMinusOne * expMinusTwo * basePowerThree) / 6;\\n    return (currentBalance * (BASE_27 + ratePerSecond * exp + secondTerm + thirdTerm)) / BASE_27;\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    ERC4626 VIEW FUNCTIONS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function totalAssets() public view override returns (uint256) {\\n    return _computeUpdatedAssets(super.totalAssets(), block.timestamp - lastUpdate);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    ERC4626 INTERACTION FUNCTIONS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function deposit(uint256 assets, address receiver) public override whenNotPaused returns (uint256 shares) {\\n    uint256 newTotalAssets = _accrue();\\n    shares = _convertToShares(assets, newTotalAssets, Math.Rounding.Floor);\\n    _deposit(_msgSender(), receiver, assets, shares);\\n  }\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function mint(uint256 shares, address receiver) public override whenNotPaused returns (uint256 assets) {\\n    uint256 newTotalAssets = _accrue();\\n    assets = _convertToAssets(shares, newTotalAssets, Math.Rounding.Ceil);\\n    _deposit(_msgSender(), receiver, assets, shares);\\n  }\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function withdraw(\\n    uint256 assets,\\n    address receiver,\\n    address owner\\n  )\\n    public\\n    override\\n    whenNotPaused\\n    returns (uint256 shares)\\n  {\\n    uint256 newTotalAssets = _accrue();\\n    shares = _convertToShares(assets, newTotalAssets, Math.Rounding.Ceil);\\n    _withdraw(_msgSender(), receiver, owner, assets, shares);\\n  }\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function redeem(\\n    uint256 shares,\\n    address receiver,\\n    address owner\\n  )\\n    public\\n    override\\n    whenNotPaused\\n    returns (uint256 assets)\\n  {\\n    uint256 newTotalAssets = _accrue();\\n    assets = _convertToAssets(shares, newTotalAssets, Math.Rounding.Floor);\\n    _withdraw(_msgSender(), receiver, owner, assets, shares);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    EIP-3009\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  function depositWithAuthorization(\\n    uint256 assets,\\n    address receiver,\\n    address owner,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    external\\n    whenNotPaused\\n    returns (uint256 shares)\\n  {\\n    uint256 newTotalAssets = _accrue();\\n    shares = _convertToShares(assets, newTotalAssets, Math.Rounding.Floor);\\n    IEIP3009(asset()).transferWithAuthorization(owner, address(this), assets, validAfter, validBefore, nonce, v, r, s);\\n    _mint(receiver, shares);\\n    emit Deposit(owner, receiver, assets, shares);\\n  }\\n\\n  function redeemWithAuthorization(\\n    uint256 shares,\\n    address receiver,\\n    address owner,\\n    uint256 validAfter,\\n    uint256 validBefore,\\n    bytes32 nonce,\\n    uint8 v,\\n    bytes32 r,\\n    bytes32 s\\n  )\\n    external\\n    whenNotPaused\\n    returns (uint256 assets)\\n  {\\n    uint256 newTotalAssets = _accrue();\\n    assets = _convertToAssets(shares, newTotalAssets, Math.Rounding.Floor);\\n    _transferWithAuthorization(owner, address(this), shares, validAfter, validBefore, nonce, v, r, s);\\n    _burn(address(this), shares);\\n    SafeERC20.safeTransfer(IERC20Metadata(asset()), receiver, assets);\\n    emit Withdraw(msg.sender, receiver, owner, assets, shares);\\n  }\\n\\n  /// @inheritdoc IEIP3009\\n  function transferWithAuthorization(\\n    address from, address to, uint256 value, uint256 validAfter,\\n    uint256 validBefore, bytes32 nonce, uint8 v, bytes32 r, bytes32 s\\n  ) external whenNotPaused {\\n    _transferWithAuthorization(from, to, value, validAfter, validBefore, nonce, v, r, s);\\n  }\\n\\n  /// @inheritdoc IEIP3009\\n  function receiveWithAuthorization(\\n    address from, address to, uint256 value, uint256 validAfter,\\n    uint256 validBefore, bytes32 nonce, uint8 v, bytes32 r, bytes32 s\\n  ) external whenNotPaused {\\n    _receiveWithAuthorization(from, to, value, validAfter, validBefore, nonce, v, r, s);\\n  }\\n\\n  function cancelAuthorization(address authorizer, bytes32 nonce, uint8 v, bytes32 r, bytes32 s) external {\\n    _cancelAuthorization(authorizer, nonce, v, r, s);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    INTERNAL HELPERS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function _convertToShares(uint256 assets, Math.Rounding rounding) internal view override returns (uint256 shares) {\\n    return _convertToShares(assets, totalAssets(), rounding);\\n  }\\n\\n  /// @notice Same as the function above except that the `totalAssets` value does not have to be recomputed here\\n  function _convertToShares(\\n    uint256 assets,\\n    uint256 newTotalAssets,\\n    Math.Rounding rounding\\n  )\\n    internal\\n    view\\n    returns (uint256 shares)\\n  {\\n    uint256 supply = totalSupply();\\n    return (assets == 0 || supply == 0)\\n      ? assets.mulDiv(BASE_18, 10 ** (IERC20Metadata(asset()).decimals()), rounding)\\n      : assets.mulDiv(supply, newTotalAssets, rounding);\\n  }\\n\\n  /// @inheritdoc ERC4626Upgradeable\\n  function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view override returns (uint256 assets) {\\n    return _convertToAssets(shares, totalAssets(), rounding);\\n  }\\n\\n  /// @notice Same as the function above except that the `totalAssets` value does not have to be recomputed here\\n  function _convertToAssets(\\n    uint256 shares,\\n    uint256 newTotalAssets,\\n    Math.Rounding rounding\\n  )\\n    internal\\n    view\\n    returns (uint256 assets)\\n  {\\n    uint256 supply = totalSupply();\\n    return (supply == 0)\\n      ? shares.mulDiv(10 ** (IERC20Metadata(asset()).decimals()), BASE_18, rounding)\\n      : shares.mulDiv(newTotalAssets, supply, rounding);\\n  }\\n\\n  function decimals() public view override(ERC4626Upgradeable, ERC20Upgradeable) returns (uint8) {\\n    return super.decimals();\\n  }\\n\\n  function _setNameAndSymbol(string memory newName, string memory newSymbol) internal virtual { }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    HELPERS\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Provides an estimated Annual Percentage Rate for base depositors on this contract\\n  function estimatedAPR() external view returns (uint256 apr) {\\n    // 365 days = 31536000 seconds\\n    return _computeUpdatedAssets(BASE_18, 31_536_000) - BASE_18;\\n  }\\n\\n  /// @notice Wrapper on top of the `computeUpdatedAssets` function\\n  function computeUpdatedAssets(uint256 _totalAssets, uint256 exp) external view returns (uint256) {\\n    return _computeUpdatedAssets(_totalAssets, exp);\\n  }\\n\\n  /*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n    GOVERNANCE\\n  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n  /// @notice Pauses the contract\\n  function togglePause() external restricted {\\n    uint8 pauseStatus = 1 - paused;\\n    paused = pauseStatus;\\n    emit ToggledPause(pauseStatus);\\n  }\\n\\n  /// @notice Toggles an address\\n  function toggleTrusted(address trustedAddress) external restricted {\\n    uint256 trustedStatus = 1 - isTrustedUpdater[trustedAddress];\\n    isTrustedUpdater[trustedAddress] = trustedStatus;\\n    emit ToggledTrusted(trustedAddress, trustedStatus);\\n  }\\n\\n  /// @notice Updates the inflation rate for depositing `asset` in this contract\\n  /// @dev Any `rate` can be set by the guardian or by a trusted address provided that it is inferior to\\n  ///the `maxRate` settable by a governor address\\n  function setRate(uint208 newRate) external onlyTrustedOrRestricted {\\n    if (newRate > maxRate) revert InvalidRate();\\n    _accrue();\\n    rate = newRate;\\n    emit RateUpdated(newRate);\\n  }\\n\\n  /// @notice Updates the maximum rate settable\\n  function setMaxRate(uint256 newMaxRate) external restricted {\\n    maxRate = newMaxRate;\\n    emit MaxRateUpdated(newMaxRate);\\n  }\\n}\\n\",\"keccak256\":\"0x35bc4498bf5819aacc440c09ed22039fd4ed63010953aa60f89316db03011fa0\",\"license\":\"BUSL-1.1\"},\"project/contracts/savings/nameable/SavingsNameable.sol\":{\"content\":\"// SPDX-License-Identifier: BUSL-1.1\\npragma solidity 0.8.28;\\n\\nimport \\\"../Savings.sol\\\";\\n\\n/// @title SavingsNameable\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @dev This contract is an authorized fork of Angle's SavingsNameable contract:\\n/// https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/savings/nameable/SavingsNameable.sol\\ncontract SavingsNameable is Savings {\\n  string internal __name;\\n\\n  string internal __symbol;\\n\\n  uint256[48] private __gapNameable;\\n\\n  /// @inheritdoc ERC20Upgradeable\\n  function name() public view override(ERC20Upgradeable, IERC20Metadata) returns (string memory) {\\n    return __name;\\n  }\\n\\n  /// @inheritdoc ERC20Upgradeable\\n  function symbol() public view override(ERC20Upgradeable, IERC20Metadata) returns (string memory) {\\n    return __symbol;\\n  }\\n\\n  /// @notice Updates the name and symbol of the token\\n  function setNameAndSymbol(string memory newName, string memory newSymbol) external restricted {\\n    _setNameAndSymbol(newName, newSymbol);\\n  }\\n\\n  function _setNameAndSymbol(string memory newName, string memory newSymbol) internal override {\\n    __name = newName;\\n    __symbol = newSymbol;\\n  }\\n}\\n\",\"keccak256\":\"0x96c15f05b1e7c1c949faf56fcc4c253df991636d8aa1998587f94dc4d038dabb\",\"license\":\"BUSL-1.1\"},\"project/contracts/utils/AccessManagedUpgradeable.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\n// OpenZeppelin Contracts (last updated v5.1.0) (access/manager/AccessManaged.sol)\\npragma solidity 0.8.28;\\n\\nimport { AuthorityUtils } from \\\"@openzeppelin/contracts/access/manager/AuthorityUtils.sol\\\";\\nimport { IAccessManager } from \\\"@openzeppelin/contracts/access/manager/IAccessManager.sol\\\";\\nimport { IAccessManaged } from \\\"@openzeppelin/contracts/access/manager/IAccessManaged.sol\\\";\\nimport { ContextUpgradeable } from \\\"@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol\\\";\\nimport { Initializable } from \\\"@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol\\\";\\n\\n/// @title AccessControl\\n/// @author Cooper Labs\\n/// @custom:contact security@cooperlabs.xyz\\n/// @dev Fork of OpenZeppelin's `AccessManagedUpgradeable` contract\\n/// updated to make _checkCanCall to return bool\\n/* solhint-disable max-line-length */\\n/// https://github.com/OpenZeppelin/openzeppelin-contracts-upgradeable/blob/master/contracts/access/manager/AccessManagedUpgradeable.sol\\n/* solhint-enable max-line-length */\\nabstract contract AccessManagedUpgradeable is Initializable, ContextUpgradeable, IAccessManaged {\\n  /// @custom:storage-location erc7201:openzeppelin.storage.AccessManaged\\n  struct AccessManagedStorage {\\n    address _authority;\\n    bool _consumingSchedule;\\n  }\\n\\n  // keccak256(abi.encode(uint256(keccak256(\\\"openzeppelin.storage.AccessManaged\\\")) - 1)) & ~bytes32(uint256(0xff))\\n  bytes32 private constant AccessManagedStorageLocation =\\n    0xf3177357ab46d8af007ab3fdb9af81da189e1068fefdc0073dca88a2cab40a00;\\n\\n  function _getAccessManagedStorage() private pure returns (AccessManagedStorage storage $) {\\n    assembly (\\\"memory-safe\\\") {\\n      $.slot := AccessManagedStorageLocation\\n    }\\n  }\\n\\n  /**\\n   * @dev Initializes the contract connected to an initial authority.\\n   */\\n  function __AccessManaged_init(address initialAuthority) internal onlyInitializing {\\n    __AccessManaged_init_unchained(initialAuthority);\\n  }\\n\\n  function __AccessManaged_init_unchained(address initialAuthority) internal onlyInitializing {\\n    _setAuthority(initialAuthority);\\n  }\\n\\n  /**\\n   * @dev Restricts access to a function as defined by the connected Authority for this contract and the\\n   * caller and selector of the function that entered the contract.\\n   *\\n   * [IMPORTANT]\\n   * ====\\n   * In general, this modifier should only be used on `external` functions. It is okay to use it on `public`\\n   * functions that are used as external entry points and are not called internally. Unless you know what you're\\n   * doing, it should never be used on `internal` functions. Failure to follow these rules can have critical security\\n   * implications! This is because the permissions are determined by the function that entered the contract, i.e. the\\n   * function at the bottom of the call stack, and not the function where the modifier is visible in the source code.\\n   * ====\\n   *\\n   * [WARNING]\\n   * ====\\n   * Avoid adding this modifier to the\\n   * https://docs.soliditylang.org/en/v0.8.20/contracts.html#receive-ether-function[`receive()`]\\n   * function or the https://docs.soliditylang.org/en/v0.8.20/contracts.html#fallback-function[`fallback()`]. These\\n   * functions are the only execution paths where a function selector cannot be unambiguously determined from the\\n   * calldata\\n   * since the selector defaults to `0x00000000` in the `receive()` function and similarly in the `fallback()`\\n   * function\\n   * if no calldata is provided. (See {_checkCanCall}).\\n   *\\n   * The `receive()` function will always panic whereas the `fallback()` may panic depending on the calldata length.\\n   * ====\\n   */\\n  modifier restricted() {\\n    address caller = _msgSender();\\n    require(_checkCanCall(caller, _msgData()), AccessManagedUnauthorized(caller));\\n    _;\\n  }\\n\\n  /// @inheritdoc IAccessManaged\\n  function authority() public view virtual returns (address) {\\n    AccessManagedStorage storage $ = _getAccessManagedStorage();\\n    return $._authority;\\n  }\\n\\n  /// @inheritdoc IAccessManaged\\n  function setAuthority(address newAuthority) public virtual {\\n    address caller = _msgSender();\\n    if (caller != authority()) {\\n      revert AccessManagedUnauthorized(caller);\\n    }\\n    if (newAuthority.code.length == 0) {\\n      revert AccessManagedInvalidAuthority(newAuthority);\\n    }\\n    _setAuthority(newAuthority);\\n  }\\n\\n  /// @inheritdoc IAccessManaged\\n  function isConsumingScheduledOp() public view returns (bytes4) {\\n    AccessManagedStorage storage $ = _getAccessManagedStorage();\\n    return $._consumingSchedule ? this.isConsumingScheduledOp.selector : bytes4(0);\\n  }\\n\\n  /**\\n   * @dev Transfers control to a new authority. Internal function with no access restriction. Allows bypassing the\\n   * permissions set by the current authority.\\n   */\\n  function _setAuthority(address newAuthority) internal virtual {\\n    AccessManagedStorage storage $ = _getAccessManagedStorage();\\n    $._authority = newAuthority;\\n    emit AuthorityUpdated(newAuthority);\\n  }\\n\\n  /**\\n   * @dev Reverts if the caller is not allowed to call the function identified by a selector. Panics if the calldata\\n   * is less than 4 bytes long.\\n   */\\n  function _checkCanCall(address caller, bytes calldata data) internal virtual returns (bool) {\\n    AccessManagedStorage storage $ = _getAccessManagedStorage();\\n    (bool immediate, uint32 delay) =\\n      AuthorityUtils.canCallWithDelay(authority(), caller, address(this), bytes4(data[0:4]));\\n    if (!immediate) {\\n      if (delay > 0) {\\n        $._consumingSchedule = true;\\n        IAccessManager(authority()).consumeScheduledOp(caller, data);\\n        $._consumingSchedule = false;\\n      } else {\\n        return false;\\n      }\\n    }\\n    return true;\\n  }\\n}\\n\",\"keccak256\":\"0x54e098edbcb4e4e232733f1be4adecdc201460ee1d500115ef8b1c0dba4857d0\",\"license\":\"MIT\"},\"project/contracts/utils/Constants.sol\":{\"content\":\"// SPDX-License-Identifier: BUSL-1.1\\npragma solidity 0.8.28;\\n\\nimport { ICbETH } from \\\"contracts/interfaces/external/coinbase/ICbETH.sol\\\";\\nimport { ISfrxETH } from \\\"contracts/interfaces/external/frax/ISfrxETH.sol\\\";\\nimport { IStETH } from \\\"contracts/interfaces/external/lido/IStETH.sol\\\";\\nimport { IRETH } from \\\"contracts/interfaces/external/rocketPool/IRETH.sol\\\";\\n\\n/*//////////////////////////////////////////////////////////////////////////////////////////////////////////////////\\n                                                 STORAGE SLOTS                                                  \\n//////////////////////////////////////////////////////////////////////////////////////////////////////////////////*/\\n\\n/// @dev Storage position of `DiamondStorage` structure\\n/// @dev Equals `keccak256(\\\"diamond.standard.diamond.storage\\\") - 1`\\nbytes32 constant DIAMOND_STORAGE_POSITION = 0xc8fcad8db84d3cc18b4c41d551ea0ee66dd599cde068d998e57d5e09332c131b;\\n\\n/// @dev Storage position of `ParallelizerStorage` structure\\n/// @dev Equals `keccak256(\\\"diamond.standard.parallelizer.storage\\\") - 1`\\nbytes32 constant TRANSMUTER_STORAGE_POSITION 